<div class="el-search" x-data="{q:"",items:[],open:false,load(){if(this.q.length<2){this.items=[];return;}fetch(`/api/search?q=${encodeURIComponent(this.q)}`).then(r=>r.json()).then(j=>{this.items=j.items||[];this.open=true;});}}"><input type="text" placeholder="{{ $settings["placeholder"] ?? "Search products..." }}" x-model="q" @input.debounce.300ms="load()"><div class="search-suggest" x-show="open"><template x-for="item in items"><a :href="item.url" x-text="item.name"></a></template></div></div>
